CREATE TABLE IF NOT EXISTS customer_chat_sessions (id VARCHAR(120) PRIMARY KEY, started_at DATETIME NOT NULL, ended_at DATETIME NULL, source ENUM('tablet','kiosk','web') NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS customer_chat_messages (id VARCHAR(120) PRIMARY KEY, session_id VARCHAR(120) NOT NULL, role ENUM('user','assistant') NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_chat_messages_session FOREIGN KEY (session_id) REFERENCES customer_chat_sessions(id) ON DELETE RESTRICT, INDEX idx_chat_messages_session (session_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS product_requests (id VARCHAR(120) PRIMARY KEY, session_id VARCHAR(120) NOT NULL, message_id VARCHAR(120) NOT NULL, raw_query VARCHAR(500) NOT NULL, normalized_query VARCHAR(500) NOT NULL, matched_product_id VARCHAR(120) NULL, status ENUM('available','unavailable','not_found') NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_product_requests_session FOREIGN KEY (session_id) REFERENCES customer_chat_sessions(id) ON DELETE RESTRICT, CONSTRAINT fk_product_requests_message FOREIGN KEY (message_id) REFERENCES customer_chat_messages(id) ON DELETE RESTRICT, CONSTRAINT fk_product_requests_product FOREIGN KEY (matched_product_id) REFERENCES products(id) ON DELETE SET NULL, INDEX idx_product_requests_normalized (normalized_query), INDEX idx_product_requests_status (status), INDEX idx_product_requests_created (created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
